<template><DetailSection title="点位资料"><FieldRow label="名称" :value="point.name"/><FieldRow label="点位类型" :value="status(point.type)"/><FieldRow label="启停状态" :value="point.enabled?'启用':'停用'"/><FieldRow label="完整性" :value="point.complete===true?'资料完整':point.complete===false?'待补齐':'未提供'"/><FieldRow label="所在地区" :value="regionPath" wide/><FieldRow label="详细地址" :value="point.address" wide/><FieldRow label="联系人" :value="point.contactName"/><FieldRow label="经营联系电话" :value="point.phone"/><FieldRow label="营业时间" :value="opening(point.opening)" wide/><FieldRow label="使用说明" :value="point.instructions" wide/><FieldRow label="坐标" :value="coordinates"/><FieldRow label="受影响商品数" :value="point.affectedGoods"/><FieldRow v-if="point.incompleteFields&&point.incompleteFields.length" label="待补字段" :value="point.incompleteFields.map(fieldName).join('、')" wide/></DetailSection></template>
<script>import {uiRead} from '@/api/stage1-usability';import {status,opening} from '../display.cjs';import DetailSection from './DetailSection';import FieldRow from './FieldRow';export default {components:{DetailSection,FieldRow},props:{point:{type:Object,required:true}},data:()=>({regionPath:'未提供',ticket:0}),computed:{coordinates(){const c=this.point.coordinates;if(!c)return '未提供';return '纬度 '+(c.latitude==null?'未提供':c.latitude)+'，经度 '+(c.longitude==null?'未提供':c.longitude);}},watch:{point:{immediate:true,deep:true,handler(){this.region();}}},beforeDestroy(){this.ticket++;},methods:{status,opening,fieldName(v){return {name:'名称',address:'地址',phone:'电话',contactName:'联系人',opening:'营业时间',provinceCode:'省',cityCode:'市',districtCode:'区县'}[v]||'待核查字段（'+v+'）';},async region(){const ticket=++this.ticket,codes=[this.point.provinceCode,this.point.cityCode,this.point.districtCode].filter(Boolean);this.regionPath=codes.length?'名称读取中…':'未提供';if(!codes.length)return;try{const names=await uiRead('/region-names',{codes:codes.join(',')});if(ticket===this.ticket)this.regionPath=codes.map(code=>{const item=names.find(r=>r.code===code);return item?item.name:'名称未提供（'+code+'）';}).join(' / ');}catch(e){if(ticket===this.ticket)this.regionPath='名称无法读取（'+codes.join(' / ')+'）';}}}};</script>
